class PersonGateway:
    def __init__(self, id, last_name, first_name, deps):
        self.id, self.last_name, self.first_name, self.deps = id, last_name, first_name, deps

    @classmethod
    def find(cls, con, id):
        row = con.execute("SELECT id, last_name, first_name, deps FROM people WHERE id = ?", (id,)).fetchone()
        return cls(*row) if row else None

    def update(self, con):
        con.execute("UPDATE people SET last_name = ?, first_name = ?, deps = ? WHERE id = ?",
                    (self.last_name, self.first_name, self.deps, self.id))
